class Solution {
public:
    string entityParser(string text) {
        const vector<pair<string, string>> entities = {
            {"&quot;", "\""}, {"&apos;", "'"}, {"&amp;", "&"},
            {"&gt;", ">"}, {"&lt;", "<"}, {"&frasl;", "/"}
        };
        string ans;
        for (int i = 0; i < (int)text.size();) {
            bool matched = false;
            if (text[i] == '&') {
                for (const auto& e : entities) {
                    if (text.compare(i, e.first.size(), e.first) == 0) {
                        ans += e.second;
                        i += e.first.size();
                        matched = true;
                        break;
                    }
                }
            }
            if (!matched) ans += text[i++];
        }
        return ans;
    }
};
